import unittest

from parse import extract_number


class TestParse(unittest.TestCase):
    def test_digits(self):
        self.assertEqual(extract_number('abc123def'), '123')
        self.assertEqual(extract_number('v2'), '2')

    def test_none(self):
        self.assertIsNone(extract_number('no digits here'))


if __name__ == '__main__':
    unittest.main()
